SELECT gen_random_uuid()::text, 'formula', '$z$', 'z Test for a Proportion', '$z = \frac{\hat{p} - p_0}{\sqrt{p_0(1 - p_0)/n}}$', NULL, 'Tests a claimed proportion.', '[{"symbol":"$\\hat{p}$","meaning":"the sample proportion"},{"symbol":"$p_0$","meaning":"the proportion claimed by H₀"},{"symbol":"$n$","meaning":"the sample size"}]'::jsonb, 'The standard error uses $p_0$, not $\hat{p}$ (unlike the interval).', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'test of hypothesis' AND s."active"), NULL, true, 'PENDING', now(), now()
