SELECT gen_random_uuid()::text, 'formula', '$t$', 'Pooled Two-Sample t Test', '$t = \frac{\bar{x}_1 - \bar{x}_2}{s_p\sqrt{\frac{1}{n_1} + \frac{1}{n_2}}},\qquad s_p^2 = \frac{(n_1 - 1)s_1^2 + (n_2 - 1)s_2^2}{n_1 + n_2 - 2}$', NULL, 'Tests whether two means differ, assuming the two populations have equal variances.', '[{"symbol":"$\\bar{x}_i, s_i, n_i$","meaning":"each sample''s mean, standard deviation and size"}]'::jsonb, 'Degrees of freedom: n₁ + n₂ − 2.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'test of hypothesis' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics'
