SELECT gen_random_uuid()::text, 'formula', '$S_{xx}$', 'Sums of Squares for Regression', '$S_{xx} = \sum x^2 - \frac{(\sum x)^2}{n},\quad S_{xy} = \sum xy - \frac{\sum x\sum y}{n},\quad S_{yy} = \sum y^2 - \frac{(\sum y)^2}{n}$', NULL, 'The corrected sums that every regression and correlation formula is built from.', '[{"symbol":"$n$","meaning":"the sample size"}]'::jsonb, 'Keep full calculator precision: these subtract nearly equal numbers.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'regression and correlation' AND s."active"), NULL, true, 'PENDING', now(), now()
