SELECT gen_random_uuid()::text, 'formula', '$r$', 'Pearson Correlation Coefficient', '$r = \frac{S_{xy}}{\sqrt{S_{xx}S_{yy}}}$', NULL, 'The strength and direction of a straight-line relation, from −1 to 1.', '[{"symbol":"$S_{xx}, S_{yy}, S_{xy}$","meaning":"the corrected sums"}]'::jsonb, 'r measures LINEAR association only; r² is the share of variation the line explains.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'regression and correlation' AND s."active"), NULL, true, 'PENDING', now(), now()
