SELECT gen_random_uuid()::text, 'formula', '$SST = SSR + SSE$', 'Regression Analysis of Variance', '$SST = SSR + SSE,\qquad SSR = \hat{\beta}_1 S_{xy},\qquad R^2 = \frac{SSR}{SST} = r^2$', NULL, 'Splits the variation in y into the part the line explains and the residual part.', '[{"symbol":"$SST$","meaning":"$S_{yy}$, the total variation"},{"symbol":"$SSE$","meaning":"the variation left unexplained"}]'::jsonb, 'The error variance is estimated by $s^2 = \frac{SSE}{n - 2}$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'regression and correlation' AND s."active"), NULL, true, 'PENDING', now(), now()
