SELECT gen_random_uuid()::text, 'formula', '$t$', 't Test for the Slope', '$t = \frac{\hat{\beta}_1}{s/\sqrt{S_{xx}}},\qquad s^2 = \frac{SSE}{n - 2},\qquad \nu = n - 2$', NULL, 'Tests whether the slope differs from zero, that is, whether x helps predict y.', '[{"symbol":"$\\hat{\\beta}_1$","meaning":"the fitted slope"},{"symbol":"$s$","meaning":"the standard error of the estimate"}]'::jsonb, 'Its square equals the regression''s $F = \frac{MSR}{MSE}$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'regression and correlation' AND s."active"), NULL, true, 'PENDING', now(), now()
