SELECT gen_random_uuid()::text, 'formula', '$r_s$', 'Spearman Rank Correlation', '$r_s = 1 - \frac{6\sum d_i^2}{n(n^2 - 1)}$', NULL, 'A correlation for ranks: any steadily rising or falling relation, not only a straight line.', '[{"symbol":"$d_i$","meaning":"the difference between the ranks of each pair"},{"symbol":"$n$","meaning":"the sample size"}]'::jsonb, 'It equals Pearson''s r computed on the ranks (when there are no ties).', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'regression and correlation' AND s."active"), NULL, true, 'PENDING', now(), now()
