SELECT gen_random_uuid()::text, 'formula', '$SST = SSTr + SSE$', 'One-Way ANOVA Sums of Squares', '$\sum_{i,j}(y_{ij} - \bar{y})^2 = \sum_i n_i(\bar{y}_i - \bar{y})^2 + \sum_{i,j}(y_{ij} - \bar{y}_i)^2$', NULL, 'The total variation splits into between-treatment and within-treatment parts.', '[{"symbol":"$y_{ij}$","meaning":"observation j of treatment i"},{"symbol":"$\\bar{y}_i, \\bar{y}$","meaning":"the treatment means and the grand mean"}]'::jsonb, 'Degrees of freedom split the same way: N − 1 = (k − 1) + (N − k).', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'analysis of variance' AND s."active"), NULL, true, 'PENDING', now(), now()
