SELECT gen_random_uuid()::text, 'formula', '$F$', 'One-Way ANOVA F Statistic', '$F = \frac{MSTr}{MSE} = \frac{SSTr/(k - 1)}{SSE/(N - k)}$', NULL, 'Tests whether several means are all equal: a large F means at least one differs.', '[{"symbol":"$k$","meaning":"the number of treatments"},{"symbol":"$N$","meaning":"the total number of observations"}]'::jsonb, 'With two treatments, F equals the square of the pooled t.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'analysis of variance' AND s."active"), NULL, true, 'PENDING', now(), now()
