SELECT gen_random_uuid()::text, 'formula', '$LSD$', 'Least Significant Difference', '$LSD = t_{\alpha/2,\,N - k}\sqrt{MSE\left(\frac{1}{n_i} + \frac{1}{n_j}\right)}$', NULL, 'After a significant F, two treatment means differ if their gap exceeds the LSD.', '[{"symbol":"$MSE$","meaning":"the ANOVA error mean square"},{"symbol":"$n_i, n_j$","meaning":"the two treatments'' sizes"}]'::jsonb, 'Use it only after the F test rejects.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'analysis of variance' AND s."active"), NULL, true, 'PENDING', now(), now()
