SELECT gen_random_uuid()::text, 'formula', '$N$', 'Runs in a Factorial Design', '$N = n\,l_1 l_2 \cdots l_k;\qquad 2^k \text{ design: } N = n\,2^k$', NULL, 'A full factorial runs every combination of factor levels, n times each.', '[{"symbol":"$l_i$","meaning":"the levels of factor i"},{"symbol":"$n$","meaning":"the replicates"}]'::jsonb, 'A 2³ design with 2 replicates needs 16 runs.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'design of experiments' AND s."active"), NULL, true, 'PENDING', now(), now()
