SELECT gen_random_uuid()::text, 'formula', '$A$', 'Main Effect in a Two-Level Design', '$A = \bar{y}_{A+} - \bar{y}_{A-}$', NULL, 'How much the response changes, on average, when a factor goes from low to high.', '[{"symbol":"$\\bar{y}_{A+}, \\bar{y}_{A-}$","meaning":"the mean response at the high and low levels of A"}]'::jsonb, 'In a $2^2$ design with $n$ replicates: $A = \frac{a + ab - b - (1)}{2n}$ (totals).', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'design of experiments' AND s."active"), NULL, true, 'PENDING', now(), now()
