SELECT gen_random_uuid()::text, 'formula', '$AB$', 'Interaction Effect in a 2² Design', '$AB = \frac{ab + (1) - a - b}{2n}$', NULL, 'Whether the effect of one factor depends on the level of the other.', '[{"symbol":"$(1), a, b, ab$","meaning":"the response totals at each combination of levels"},{"symbol":"$n$","meaning":"the replicates"}]'::jsonb, 'A large interaction makes the main effects misleading on their own.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'design of experiments' AND s."active"), NULL, true, 'PENDING', now(), now()
