SELECT gen_random_uuid()::text, 'formula', '$2^{k - p}$', 'Fractional Factorial Runs', '$N = 2^{k - p}$', NULL, 'A fraction of a two-level design that screens many factors in few runs, at the cost of aliasing some effects.', '[{"symbol":"$k$","meaning":"the factors"},{"symbol":"$p$","meaning":"how many times the full design is halved"}]'::jsonb, 'A half fraction of 2⁵ needs 16 runs instead of 32.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'design of experiments' AND s."active"), NULL, true, 'PENDING', now(), now()
