SELECT gen_random_uuid()::text, 'formula', '$\nu_E$', 'Randomized Complete Block Design', '$SST = SSTr + SSB + SSE;\qquad \nu: (ab - 1) = (a - 1) + (b - 1) + (a - 1)(b - 1)$', NULL, 'Each block (a batch, a day, a machine) gets every treatment, so block differences are removed from the error.', '[{"symbol":"$a$","meaning":"the treatments"},{"symbol":"$b$","meaning":"the blocks"}]'::jsonb, '$F = \frac{MSTr}{MSE}$ with $a - 1$ and $(a - 1)(b - 1)$ degrees of freedom.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Engineering Data Analytics' AND t."subject" = 'Mathematics' AND s."normKey" = 'design of experiments' AND s."active"), NULL, true, 'PENDING', now(), now()
